module edge_detect(
    input clk, 
    input rst_n, 
    input a,
    output rise, 
    output down
);
// Register declarations
reg a_reg;
reg rise_reg;
reg down_reg;
// Sequential logic block triggered on positive edge of clk
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Asynchronous reset
        a_reg <= 1'b0;
        rise_reg <= 1'b0;
        down_reg <= 1'b0;
    end else begin
        // Update previous value of a
        a_reg <= a;

        // Detect rising edge
        if ((a == 1'b1 && a_reg == 1'b0)) begin
            rise_reg <= 1'b1;
        end else begin
            rise_reg <= 1'b0;
        end

        // Detect falling edge
        if ((a == 1'b0 && a_reg == 1'b1)) begin
            down_reg <= 1'b1;
        end else begin
            down_reg <= 1'b0;
        end
    end
end
// Assign output signals
assign rise = rise_reg;
assign down = down_reg;
endmodule
